test("429 and 500 -> JEV_UNAVAILABLE", async () => {
    try {
      await judgeOnce(fakeFetch({ error: "rate limited" }, 429));
      expect.unreachable();
    } catch (e) {
      expectMeasureError("JEV_UNAVAILABLE")(e);
    }
    try {
      await judgeOnce(fakeFetch({ error: "server exploded" }, 500));
      expect.unreachable();
    } catch (e) {
      expectMeasureError("JEV_UNAVAILABLE")(e);
    }
  });
